SELECT p.id AS planId, p.plan_code AS planCode, v.name_zh AS shipName, v.name_en AS englishName, pl.pilot_name AS pilotName, DATE_FORMAT(COALESCE(p.actual_start_time, p.plan_start_time), '%Y-%m-%d %H:%i') AS time, COALESCE(p.end_location_name, p.start_location_name) AS berth, CASE WHEN p.operation_type_flag LIKE '%进%' THEN '进港' WHEN p.operation_type_flag LIKE '%出%' THEN '出港' WHEN p.operation_type_flag LIKE '%移%' THEN '移泊' ELSE COALESCE(p.operation_type_flag, '-') END AS dynamic, FORMAT(v.gross_tonnage, 2) AS grossTonnage, FORMAT(v.net_tonnage, 2) AS netTonnage, FORMAT(v.deadweight, 2) AS deadWeight, FORMAT(v.vessel_length, 2) AS length, FORMAT(v.vessel_width, 2) AS width, FORMAT(v.full_load_draft, 2) AS draft, v.nationality AS nationality, v.vessel_call_sign AS callSign, v.imo_number AS imoNumber FROM pilotage_plans p INNER JOIN vessels v ON v.id = p.vessel_id LEFT JOIN pilots pl ON pl.id = p.assigned_pilot_id WHERE p.plan_status IN ('ONGOING','COMPLETED','CERTIFICATED','BILLED','PAID')
AND ( p.plan_code LIKE CONCAT('%', #{keyword}, '%') OR v.name_zh LIKE CONCAT('%', #{keyword}, '%') OR v.name_en LIKE CONCAT('%', #{keyword}, '%') OR pl.pilot_name LIKE CONCAT('%', #{keyword}, '%') )
AND COALESCE(p.actual_start_time, p.plan_start_time) >= #{startDate}
AND COALESCE(p.actual_start_time, p.plan_start_time) <= #{endDate}
ORDER BY COALESCE(p.actual_start_time, p.plan_start_time) DESC LIMIT #{offset}, #{size}

SELECT COUNT(1) FROM pilotage_plans p INNER JOIN vessels v ON v.id = p.vessel_id LEFT JOIN pilots pl ON pl.id = p.assigned_pilot_id WHERE p.plan_status IN ('ONGOING','COMPLETED','CERTIFICATED','BILLED','PAID')
AND ( p.plan_code LIKE CONCAT('%', #{keyword}, '%') OR v.name_zh LIKE CONCAT('%', #{keyword}, '%') OR v.name_en LIKE CONCAT('%', #{keyword}, '%') OR pl.pilot_name LIKE CONCAT('%', #{keyword}, '%') )
