SELECT p.id AS planId, p.plan_code AS planCode, v.name_zh AS shipName, v.name_en AS englishName, t.tugboat_name AS tugboatName, t.call_sign AS tugboatCallSign, FORMAT(t.bollard_pull, 2) AS bollardPull, DATE_FORMAT(COALESCE(p.actual_start_time, p.plan_start_time), '%Y-%m-%d %H:%i') AS time, COALESCE(p.end_location_name, p.start_location_name) AS berth, CASE WHEN p.operation_type_flag LIKE '%进%' THEN '进港' WHEN p.operation_type_flag LIKE '%出%' THEN '出港' WHEN p.operation_type_flag LIKE '%移%' THEN '移泊' ELSE COALESCE(p.operation_type_flag, '-') END AS dynamic FROM plan_tugboat_assignments a INNER JOIN pilotage_plans p ON p.id = a.plan_id INNER JOIN vessels v ON v.id = p.vessel_id INNER JOIN tugboats t ON t.id = a.tugboat_id WHERE p.plan_status IN ('ONGOING','COMPLETED','CERTIFICATED','BILLED','PAID')
AND ( p.plan_code LIKE CONCAT('%', #{keyword}, '%') OR v.name_zh LIKE CONCAT('%', #{keyword}, '%') OR v.name_en LIKE CONCAT('%', #{keyword}, '%') OR t.tugboat_name LIKE CONCAT('%', #{keyword}, '%') OR t.call_sign LIKE CONCAT('%', #{keyword}, '%') )
